import { env as cfEnv } from 'cloudflare:workers';

/**
 * Typed bindings (DB, JOBS, ASSETS), vars and secrets for server code.
 * Types: worker-configuration.d.ts, generated by `npm run types` from wrangler.jsonc
 * + .dev.vars.example (add new secret names there first).
 * Every secret is optional at runtime: check before use, degrade gracefully.
 */
export const env = cfEnv as Env;

/** Feature flags derived from which secrets/bindings exist. Booleans only: safe to expose. */
export function features() {
  return {
    admin: Boolean(env.ADMIN_PASSWORD),
    stripe: Boolean(env.STRIPE_SECRET_KEY),
    stripeWebhook: Boolean(env.STRIPE_WEBHOOK_SECRET),
    queue: Boolean(env.JOBS),
    db: Boolean(env.DB),
  };
}
